import {copy} from './music.js';
import {firstClipSpace,notesInClip} from './clips.js';
import {patternCompatible,patternInstances} from './patterns-core.js';
import {planPatternSeries,planPatternInstances} from './pattern-arrange.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),bar=beat=>+(beat/4+1).toFixed(4);
const labels={mute:'静音所选音块',unmute:'取消所选块静音',detach:'只让所选块独立化',delete:'删除所选音块与内部音符'};
export function createPatternArrangeUI({getProject,getRevision,getSelection,commit,protectedChange,modal,toast,library,locate}){
 let flow=0;const invalidate=()=>++flow;
 function session(d,root,at){const ticket=invalidate();d.addEventListener('close',()=>{if(ticket===flow)invalidate()},{once:true});return()=>{if(ticket!==flow||at!==getRevision()||!root.isConnected||!d.open)throw Error('工程或窗口已改变，请重新打开 Pattern 编排。')}}
 function place(id){
  const before=copy(getProject()),source=before.patterns?.find(p=>p.id===id);if(!source)return toast('源乐句已不存在');
  const at=getRevision(),targets=before.tracks.filter(t=>patternCompatible(source,t)),initial=targets.find(t=>t.id===getSelection().trackId)||targets.find(t=>t.instrument===source.instrument)||targets[0];let result=null;
  const d=modal('放置 Pattern · 一次编排多份',`<div class="pattern-form pattern-series"><p><strong>${escape(source.name)}</strong> · ${source.length/4} 小节 · ${source.notes.length} 音符。只编排，不播放、不调用模型。</p><div class="chord-fields"><label>目标轨道<select id="pattern-track">${targets.map(t=>`<option value="${escape(t.id)}" ${t===initial?'selected':''}>${escape(t.name)}</option>`).join('')}</select></label><label>第一份起始小节<input id="pattern-start" type="number" min="1" max="65" step="0.0625" value="${initial?(firstClipSpace(initial,source.length,before.bars*4)??before.bars*4)/4+1:1}"></label><label>放置份数<input id="pattern-count" type="number" min="1" max="32" step="1" value="1"></label><label>每份起点间隔（拍）<input id="pattern-interval" type="number" min="0.25" max="256" step="0.25" value="${source.length}"></label></div><label class="check-label"><input id="pattern-linked" type="checkbox" checked>共享关联：之后的库内共享编辑同步这些块</label><label class="check-label"><input id="pattern-extend" type="checkbox">需要时空白延长工程（最多 64 小节）</label><div id="pattern-preview" class="chord-preview" role="status"></div><div class="modal-notice">默认只放 1 份；间隔等于句长时首尾相接，大于句长会留空隙。空音块也占位置，有一份碰撞 / 越界 / 超限就整组拒绝。不勾选共享关联则每份独立编辑；普通复制仍不共享。新区域中其他轨道不重复，旧源 / 音块 / 标签 / 混音保持。作为一次编辑可撤销。</div><div id="pattern-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" id="pattern-back">取消，返回库</button><button class="accent" id="pattern-apply">按预览放置全部</button>');
  const root=$('.pattern-series'),guard=session(d,root,at),read=()=>{guard();return planPatternSeries(before,id,$('#pattern-track').value,{start:$('#pattern-start').value===''?NaN:(+$('#pattern-start').value-1)*4,count:$('#pattern-count').value===''?NaN:+$('#pattern-count').value,interval:$('#pattern-interval').value===''?NaN:+$('#pattern-interval').value,linked:$('#pattern-linked').checked,extend:$('#pattern-extend').checked})};
  const update=()=>{result=null;try{result=read();const s=result.stats,target=targets.find(t=>t.id===result.trackId);$('#pattern-preview').innerHTML=`<h3>${s.count} 份 · ${s.linked?'↔ 共享引用':'独立副本'} · 新增 ${s.addedNotes} 音符</h3><p>${escape(target.name)}：第 ${result.rows.map(r=>bar(r.start)).join('、')} 小节。<br>${s.extended?`工程 ${s.barsBefore} → ${s.barsAfter} 小节，仅空白延长。`:'工程长度保持。'}关联数 ${s.referencesBefore} → ${s.referencesAfter}。</p><div class="pattern-series-map">${result.rows.map(r=>`<span>第 ${r.index} 份 · 第 ${bar(r.start)} 小节起 · ${source.length/4} 小节</span>`).join('')}</div>`;$('#pattern-error').textContent='';$('#pattern-apply').disabled=false}catch(e){$('#pattern-preview').textContent='未放置任何内容，请调整起点、份数、间隔或延长选项。';$('#pattern-error').textContent=e.message;$('#pattern-apply').disabled=true}};
  $('#pattern-track').onchange=()=>{const t=targets.find(t=>t.id===$('#pattern-track').value);$('#pattern-start').value=(firstClipSpace(t,source.length,before.bars*4)??before.bars*4)/4+1;update()};
  for(const name of ['pattern-start','pattern-count','pattern-interval','pattern-linked','pattern-extend']){$('#'+name).oninput=update;$('#'+name).onchange=update}
  $('#pattern-back').onclick=()=>library(id);$('#pattern-apply').onclick=()=>{try{guard();if(!result)throw Error('请先得到合法放置预览');const s=result.stats;if(commit(result.project,{trackId:result.trackId,clipId:result.clipIds[0]})){d.close();toast(`已放置 ${s.count} 份${s.linked?'共享乐句':'独立副本'}，新增 ${s.addedNotes} 音符，可一次撤销。`)}}catch(e){$('#pattern-error').textContent=e.message;$('#pattern-apply').disabled=true}};update();
 }
 function manage(id){
  const before=copy(getProject()),source=before.patterns?.find(p=>p.id===id);if(!source)return toast('源乐句已不存在');
  const refs=patternInstances(before,id),at=getRevision(),selected=new Set();let page=0,result=null,busy=false;
  const d=modal('管理关联音块 · 只改所选',`<div class="pattern-form pattern-instance-manager"><p><strong>${escape(source.name)}</strong> · ${refs.length} 个当前关联块。先选块，再选操作；默认一个也不选。不包含普通复制或已经独立化的块。</p><label class="modal-label" for="pattern-instance-action">对所选关联块做什么</label><select id="pattern-instance-action">${Object.entries(labels).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select><div class="transfer-tools"><button class="quiet compact" id="pattern-instance-all">全选关联块</button><button class="quiet compact" id="pattern-instance-none">全不选</button><span>跨页保留选择 · 不播放</span></div><div id="pattern-instance-list" class="transfer-list"></div><div class="pattern-pagination"><button class="quiet compact" id="pattern-instance-prev">上一页</button><span id="pattern-instance-page"></span><button class="quiet compact" id="pattern-instance-next">下一页</button></div><div id="pattern-preview" class="chord-preview" role="status"></div><div class="modal-notice">块静音只影响这些块，轨道的 M / S 和混音不变；取消块静音不保证发声（轨道还可能静音 / 非独奏）。独立化保留现有全部音符及 IDs，之后不接收源编辑。删除同时移除所选块内部音符，不删除源、不挤走其他块、不缩短工程，也不删除段落 / 练习范围。先备份旧工程，再作为一次可撤销编辑；预览 / 查看位置不播放、不改音乐。</div><div id="pattern-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" id="pattern-back">取消，返回库</button><button class="accent" id="pattern-apply">先选择关联块</button>');
  const root=$('.pattern-instance-manager'),guard=session(d,root,at);
  function rows(){const start=page*8;$('#pattern-instance-list').innerHTML=refs.slice(start,start+8).map((r,i)=>{const t=before.tracks.find(t=>t.id===r.trackId),c=t.clips.find(c=>c.id===r.clipId);return`<article class="transfer-row"><label><input type="checkbox" data-instance="${escape(r.clipId)}" ${selected.has(r.clipId)?'checked':''} aria-label="选择关联块 ${start+i+1} ${escape(r.trackName)} 第 ${bar(r.start)} 小节"><span><strong>${escape(r.trackName)} · 第 ${bar(r.start)} 小节</strong><small>${escape(r.clipName)} · ${r.length/4} 小节 · ${notesInClip(t,c).length} 音符 · ${r.muted?'块静音':'块未静音'}</small></span></label><button class="quiet compact" data-instance-locate="${escape(r.clipId)}" aria-label="查看关联块 ${start+i+1} 位置">查看位置</button></article>`}).join('')||'<p>这个源还没有关联块，可先放置。独立副本不会出现在此表。</p>';$('#pattern-instance-page').textContent=`${page+1} / ${Math.max(1,Math.ceil(refs.length/8))} 页`;$('#pattern-instance-prev').disabled=page===0;$('#pattern-instance-next').disabled=(page+1)*8>=refs.length;$('#pattern-instance-all').disabled=!refs.length}
  function update(){result=null;try{guard();result=planPatternInstances(before,id,{clipIds:[...selected],action:$('#pattern-instance-action').value});const s=result.stats;$('#pattern-preview').innerHTML=`<h3>选 ${s.selected} 块 · ${s.changed} 块将改变</h3><p>${escape(labels[result.action])}。所选块内共 ${s.selectedNotes} 音符${result.action==='delete'?`，将删除 ${s.deletedNotes} 音符`: '，音符内容和 IDs 保持'}。<br>关联 ${s.referencesBefore} → ${s.referencesAfter}；工程音符 ${s.projectNotesBefore} → ${s.projectNotesAfter}。源乐句与未选块保持。</p>`;$('#pattern-error').textContent=s.changed?'':'所选块已经处于目标静音状态，没有需要改变的内容。';$('#pattern-apply').textContent='备份并'+labels[result.action];$('#pattern-apply').classList.toggle('danger',result.action==='delete');$('#pattern-apply').disabled=!s.changed||busy}catch(e){$('#pattern-preview').textContent=selected.size?'没有应用，请检查选块和操作。':'尚未选择关联块，工程没有改变。';$('#pattern-error').textContent=selected.size?e.message:'';$('#pattern-apply').textContent='先选择关联块';$('#pattern-apply').disabled=true}}
  $('#pattern-instance-list').onchange=e=>{const id=e.target.dataset.instance;if(!id||busy)return;e.target.checked?selected.add(id):selected.delete(id);update()};
  $('#pattern-instance-list').onclick=e=>{const clipId=e.target.closest('[data-instance-locate]')?.dataset.instanceLocate;if(!clipId||busy)return;try{guard();const r=refs.find(x=>x.clipId===clipId);d.close();locate(r.trackId,r.clipId);toast('已查看关联块位置，没有播放或改动音乐。')}catch(e){$('#pattern-error').textContent=e.message}};
  $('#pattern-instance-all').onclick=()=>{if(busy)return;refs.forEach(r=>selected.add(r.clipId));rows();update()};$('#pattern-instance-none').onclick=()=>{if(busy)return;selected.clear();rows();update()};$('#pattern-instance-prev').onclick=()=>{if(busy)return;page--;rows();update()};$('#pattern-instance-next').onclick=()=>{if(busy)return;page++;rows();update()};$('#pattern-instance-action').onchange=()=>{if(!busy)update()};$('#pattern-back').onclick=()=>library(id);
  $('#pattern-apply').onclick=async()=>{try{guard();if(!result?.stats.changed||busy)throw Error('请先选择有变化的关联块');const planned=result;busy=true;root.querySelectorAll('input,select,button').forEach(node=>node.disabled=true);$('#pattern-apply').disabled=true;$('#pattern-error').textContent='正在保存操作前版本；工程尚未改变…';let applied=false;
    await protectedChange(({fallback=false}={})=>{try{if(fallback){if(at!==getRevision())throw Error('工程已改变，请重新管理关联块')}else guard();if(commit(planned.project,undefined,{restart:planned.action!=='detach'})){applied=true;toast(`已${labels[planned.action]} · ${planned.stats.changed} 块，可一次撤销。`);library(id)}}catch(e){toast(e.message)}},'管理 Pattern 前 · '+source.name);
    if(!applied&&root.isConnected&&d.open){busy=false;root.querySelectorAll('input,select,button').forEach(node=>node.disabled=false);rows();update()}
   }catch(e){if(root.isConnected){$('#pattern-error').textContent=e.message;$('#pattern-apply').disabled=true}else toast(e.message)}};rows();update();
 }
 return{place,manage,invalidate};
}
